{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Aromatic care in {{CITY}}, {{STATE}}</title>
  <meta name="description" content="A calm, scent-led practice that may support emotional balance and simple rituals — local aromatherapy sessions, custom blends, and a boutique of rolled scents.">
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="split-diagonal">
  <svg class="page-pattern" aria-hidden="true" width="0" height="0">
    <defs>
      <pattern id="p" patternUnits="userSpaceOnUse" width="40" height="40">
        <rect width="40" height="40" fill="#f7f6f4" />
        <path d="M0 20 L10 10 L20 20 L30 10 L40 20" stroke="#efe7d6" stroke-width="1" fill="none" />
      </pattern>
    </defs>
  </svg>

  <header class="site-header">
    <div class="wrap">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Main navigation">
        <a href="services.html">Offerings</a>
        <a href="blends.html">Custom Blends</a>
        <a href="shop.html">Boutique</a>
        <a href="pricing.html">Rates</a>
        <a href="about.html">Our Story</a>
        <a href="book.html" class="cta">{{PRIMARY_CTA_LABEL}}</a>
        <a href="contact.html">Connect</a>
      </nav>
      <button class="menu-toggle" aria-expanded="false">Menu</button>
    </div>
  </header>

  <main>
    <!-- HERO -->
    <section class="hero reveal" id="hero">
      <div class="wrap hero-inner">
        <div class="hero-copy">
          <h1>Small scent rituals for steadier moments</h1>
          <p class="lead">Guided aromatherapy sessions, approachable blending, and retail finds to tuck into daily life. Scents, thoughtfully suggested to may support calm, clarity, and restful evenings.</p>
          <p class="meta">Call <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
          <p><a class="primary" href="{{PRIMARY_CTA_URL}}">Reserve a Session</a></p>
        </div>
        <div class="hero-visual" aria-hidden="true">
          <svg class="diagonal" viewBox="0 0 600 400" preserveAspectRatio="none" role="img">
            <defs>
              <linearGradient id="g1" x1="0" x2="1">
                <stop offset="0" stop-color="#f6efe6" />
                <stop offset="1" stop-color="#efe8f2" />
              </linearGradient>
            </defs>
            <path d="M0,0 L600,0 L600,400 L0,280 Z" fill="url(#g1)" />
            <rect x="20" y="30" width="240" height="320" rx="12" fill="#fff" opacity="0.6" />
            <g transform="translate(50,60)" fill="#e7dcd0" opacity="0.9">
              <circle cx="40" cy="40" r="24" />
              <rect x="0" y="80" width="120" height="160" rx="10" />
              <circle cx="90" cy="260" r="18" />
            </g>
          </svg>
        </div>
      </div>
    </section>

    <!-- GALLERY -->
    <section class="gallery reveal" id="gallery">
      <div class="wrap">
        <h2>Scenes from the practice</h2>
        <p class="sub">Small compositions and everyday tools that make scent approachable.</p>
        <div class="grid">
          <div class="tile tile-1" style="background-image:linear-gradient(135deg,#efe8f2,#f7f3ec)"><span>Consultations</span></div>
          <div class="tile tile-2" style="background-image:linear-gradient(135deg,#f1f6f0,#f8efe8)"><span>Custom roll-ons</span></div>
          <div class="tile tile-3" style="background-image:linear-gradient(135deg,#fff7e6,#f3f1fb)"><span>Blend jars</span></div>
          <div class="tile tile-4" style="background-image:linear-gradient(135deg,#f9f4ef,#eef7f2)"><span>Packaging</span></div>
        </div>
      </div>
    </section>

    <!-- WHAT TO EXPECT (includes Session Planner) -->
    <section class="what-to-expect reveal" id="what-to-expect">
      <div class="wrap">
        <h2>What a session feels like</h2>
        <p class="sub">A guided conversation, scent exploration, and a tiny set of practices you can carry home. Sessions are safety-forward and paced to your comfort.</p>

        <div class="cols">
          <div>
            <h3>Structure</h3>
            <ul>
              <li>Brief intake and scent preferences</li>
              <li>Guided aroma exploration and breathing practice</li>
              <li>Personalized suggestions and a take-home sample</li>
            </ul>
          </div>
          <div>
            <h3>Safety notes</h3>
            <p>We will discuss dilution, perform a small patch test when needed, and advise gently around pregnancy, pets, and sensitive skin. No medical claims — scents may support wellbeing in subtle ways.</p>
          </div>
        </div>

        <div class="planner" id="session-planner">
          <h3>Session Planner — sketch your personalized plan</h3>
          <p class="muted">Pick preferences and we'll create a short plan you can copy or save.</p>
          <form id="planner-form">
            <label>Primary intention (what you'd like to invite)</label>
            <input name="intention" placeholder="calm, focus, restful sleep..." />

            <label>Current mood</label>
            <select name="mood">
              <option value="neutral">Neutral</option>
              <option value="stressed">Stressed</option>
              <option value="tired">Tired</option>
              <option value="scattered">Scattered</option>
            </select>

            <label>Session length</label>
            <select name="length">
              <option value="30">30 minutes</option>
              <option value="45">45 minutes</option>
              <option value="60">60 minutes</option>
            </select>

            <label>Preferred scent family</label>
            <select name="scent">
              <option value="floral">Floral & soft</option>
              <option value="citrus">Citrus & bright</option>
              <option value="earthy">Earthy & grounding</option>
              <option value="spice">Warm spice</option>
            </select>

            <label><input type="checkbox" name="pets" /> I have pets at home</label>
            <label><input type="checkbox" name="pregnancy" /> I am pregnant or breastfeeding</label>

            <div class="planner-actions">
              <button type="button" id="build-plan">Build Plan</button>
              <button type="button" id="copy-plan">Copy Summary</button>
            </div>
          </form>

          <pre id="plan-output" aria-live="polite">Your plan will appear here.</pre>
        </div>

      </div>
    </section>

    <!-- OBJECTIONS / FAQ -->
    <section class="objections reveal" id="objections">
      <div class="wrap">
        <h2>Common questions & answers</h2>
        <details>
          <summary>Are these treatments safe around pets?</summary>
          <p>We consider animals in every recommendation. Some essential oils can be irritating to pets; we'll adapt blends and discuss safe storage and use. Always keep oils out of reach and consult your vet for specific concerns.</p>
        </details>
        <details>
          <summary>Pregnancy and sensitive skin — what to expect?</summary>
          <p>We avoid potentially problematic oils for pregnancy and will suggest gentle dilution and a patch test for sensitive skin. Your comfort and safety guide every suggestion.</p>
        </details>
        <details>
          <summary>Do you make blends I can buy?</summary>
          <p>Yes — a small boutique of ready blends, travel-rolls, and ritual kits are available in the shop. Blends are retail add-ons and come with usage and dilution guidance.</p>
        </details>
      </div>
    </section>

    <!-- CALL TO ACTION -->
    <section class="cta reveal" id="final-cta">
      <div class="wrap">
        <h2>Ready to try a small ritual?</h2>
        <p class="sub">Book a short consultation to explore scent and bring home a simple practice tailored to your life.</p>
        <p><a class="primary large" href="{{PRIMARY_CTA_URL}}">Schedule a Visit</a> <a class="secondary" href="book.html">See Booking Options</a></p>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="wrap">
      <div class="left">
        <strong>{{BUSINESS_NAME}}</strong>
        <div class="muted">Serving {{CITY}}, {{STATE}}</div>
      </div>
      <div class="right">
        <nav>
          <a href="about.html">About</a>
          <a href="contact.html">Contact</a>
          <a href="shop.html">Shop</a>
        </nav>
        <div class="muted">© <span id="year"></span></div>
      </div>
    </div>
  </footer>

</body>
</html>"} 
