{"path":"assets/css/styles.css","content":"/* Core layout and visual system */
:root{--accent:#8c6a9f;--muted:#6b6b6b;--bg:#faf8f5;--maxw:1100px;--radius:10px}
*{box-sizing:border-box}
html,body{height:100%}
body{font-family:system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;line-height:1.45;color:#222;background:var(--bg);margin:0}
.wrap{max-width:var(--maxw);margin:0 auto;padding:28px}
.site-header{background:linear-gradient(90deg,rgba(255,255,255,0.8),rgba(255,255,255,0.6));backdrop-filter:blur(4px);position:sticky;top:0;z-index:50;border-bottom:1px solid rgba(0,0,0,0.04)}
.site-header .wrap{display:flex;align-items:center;gap:12px}
.brand{font-weight:700;color:#2b2b2b;text-decoration:none}
.main-nav{margin-left:auto;display:flex;gap:12px;align-items:center}
.main-nav a{color:#333;text-decoration:none;padding:8px 10px;border-radius:8px}
.main-nav a.cta{background:var(--accent);color:white}
.menu-toggle{display:none}
.hero{padding:40px 0}
.split-diagonal .hero-inner{display:flex;gap:24px;align-items:stretch}
.hero-copy{flex:1}
.hero-copy h1{font-size:clamp(28px,4vw,40px);margin:0 0 12px}
.lead{color:var(--muted);margin:0 0 18px}
.hero-visual{width:420px;flex:0 0 420px}
.diagonal{width:100%;height:100%}
.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:18px}
.tile{height:120px;border-radius:12px;display:flex;align-items:flex-end;padding:12px;color:#555;font-weight:600}
.cols{display:flex;gap:24px;margin-top:20px}
.cols > div{flex:1}
.planner{margin-top:18px;background:linear-gradient(180deg,#fff,#fbfaf9);padding:16px;border-radius:10px;border:1px solid rgba(0,0,0,0.04)}
.planner label{display:block;margin:8px 0 4px;font-size:14px}
.planner input[type=text], .planner input[name], .planner select{width:100%;padding:8px;border-radius:8px;border:1px solid rgba(0,0,0,0.08)}
.planner-actions{display:flex;gap:10px;margin-top:12px}
button{cursor:pointer}
button.primary, .primary{background:var(--accent);color:#fff;padding:10px 14px;border-radius:8px;text-decoration:none;border:none}
button.secondary, .secondary{background:transparent;border:1px solid rgba(0,0,0,0.06);padding:10px 12px;border-radius:8px}
#plan-output{white-space:pre-wrap;background:#fff;border:1px dashed rgba(0,0,0,0.06);padding:12px;border-radius:8px;margin-top:12px}
details{margin-top:12px;background:#fff;padding:12px;border-radius:10px;border:1px solid rgba(0,0,0,0.04)}
.cta{padding:36px 0;text-align:center}
.cta .primary.large{padding:14px 20px;font-size:16px}
.site-footer{border-top:1px solid rgba(0,0,0,0.04);margin-top:40px;background:linear-gradient(180deg,#faf8f5,#f7f6f4)}
.site-footer .wrap{display:flex;justify-content:space-between;align-items:center;padding:20px}
.muted{color:var(--muted);font-size:13px}
/* Responsive */
@media (max-width:900px){
  .grid{grid-template-columns:repeat(2,1fr)}
  .hero-inner{flex-direction:column}
  .hero-visual{width:100%;height:200px}
  .main-nav{display:none}
  .menu-toggle{display:block;margin-left:auto}
}
/* Reveal animation */
.reveal{opacity:0;transform:translateY(18px);transition:opacity 560ms ease,transform 560ms cubic-bezier(.2,.9,.3,1)}
.reveal.is-visible{opacity:1;transform:none}
@media (prefers-reduced-motion: reduce){
  .reveal{transition:none;opacity:1;transform:none}
}
/* decorative pattern usage */
body::before{content:"";position:fixed;inset:0;background-image:url('../assets/img/pattern.svg');opacity:0.06;pointer-events:none;mix-blend-mode:multiply}
"} 
{"path":"assets/js/main.js","content":"(function(){
  // Year in footer
  document.addEventListener('DOMContentLoaded',function(){
    var y = new Date().getFullYear();
    var el = document.getElementById('year'); if(el) el.textContent = y;

    // Simple mobile menu
    var btn = document.querySelector('.menu-toggle');
    var nav = document.querySelector('.main-nav');
    if(btn && nav){
      btn.addEventListener('click',function(){
        var open = btn.getAttribute('aria-expanded') === 'true';
        btn.setAttribute('aria-expanded', String(!open));
        nav.style.display = open ? '' : 'flex';
      });
    }

    // Scroll-reveal
    var prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    var items = document.querySelectorAll('.reveal');
    if(prefersReduced){
      items.forEach(function(i){ i.classList.add('is-visible'); });
    } else if('IntersectionObserver' in window){
      var obs = new IntersectionObserver(function(entries){
        entries.forEach(function(e){ if(e.isIntersecting) { e.target.classList.add('is-visible'); obs.unobserve(e.target); } });
      },{threshold:0.12});
      items.forEach(function(i){ obs.observe(i); });
    } else {
      // fallback
      items.forEach(function(i){ i.classList.add('is-visible'); });
    }

    // Session Planner logic
    var form = document.getElementById('planner-form');
    var buildBtn = document.getElementById('build-plan');
    var copyBtn = document.getElementById('copy-plan');
    var output = document.getElementById('plan-output');

    function getFormData(){
      var fd = {};
      if(!form) return fd;
      var f = new FormData(form);
      fd.intention = (f.get('intention')||'').trim();
      fd.mood = f.get('mood')||'';
      fd.length = f.get('length')||'';
      fd.scent = f.get('scent')||'';
      fd.pets = f.get('pets')?true:false;
      fd.pregnancy = f.get('pregnancy')?true:false;
      return fd;
    }

    function buildPlanText(data){
      var lines = [];
      lines.push('{{BUSINESS_NAME}} — session sketch');
      lines.push('Intention: ' + (data.intention || '—')); 
      lines.push('Mood: ' + data.mood);
      lines.push('Length: ' + data.length + ' minutes');
      lines.push('Suggested scent family: ' + data.scent);
      lines.push('Notes:');
      lines.push('- Brief intake to explore scent history and sensitivities.');
      lines.push('- Guided scent sampling (we will suggest gentle dilutions).');
      lines.push('- Simple at-home ritual to try for 1–2 weeks.');

      if(data.pets) lines.push('- Pet note: recommendations will avoid oils known to irritate animals and include storage guidance.');
      if(data.pregnancy) lines.push('- Pregnancy/nursing note: we will select pregnancy-safe options and suggest patch testing.');

      lines.push('Safety reminder: No medical claims are made. Scents may support wellbeing for some people; we emphasize dilution and patch tests.');
      lines.push('Contact: {{PHONE}} | {{EMAIL}}');
      return lines.join('\n');
    }

    if(buildBtn){
      buildBtn.addEventListener('click',function(){
        var data = getFormData();
        var txt = buildPlanText(data);
        output.textContent = txt;
      });
    }

    if(copyBtn){
      copyBtn.addEventListener('click',function(){
        var text = output.textContent || '';
        if(!text) return;
        if(navigator.clipboard && navigator.clipboard.writeText){
          navigator.clipboard.writeText(text).then(function(){
            copyBtn.textContent = 'Copied';
            setTimeout(function(){ copyBtn.textContent = 'Copy Summary'; },1400);
          }).catch(function(){ fallbackCopy(text); });
        } else {
          fallbackCopy(text);
        }
      });
    }

    function fallbackCopy(text){
      var ta = document.createElement('textarea');
      ta.value = text; document.body.appendChild(ta); ta.select();
      try{ document.execCommand('copy'); }catch(e){}
      document.body.removeChild(ta);
      alert('Plan copied to clipboard');
    }

  });
})();"} 
